from itertools import combinations

PRICE_PER_BOOK_CENTS = 800
DISCOUNTS_PERCENT = {
    1: 0,
    2: 5,
    3: 10,
    4: 20,
    5: 25,
}

def _group_price_cents(size):
    return (size * PRICE_PER_BOOK_CENTS * (100 - DISCOUNTS_PERCENT[size])) // 100

def total(basket):
    """
    Calculate the lowest possible price for a basket of books from a 5-book series.
    Returns the price in cents as an integer.

    The basket is expected to be a list. It can be either:
      - a list of book ids (ints) where each element is 0..4 or 1..5, e.g. [0,0,1,2,3]
      - OR a list of counts per volume of length 5, e.g. [2,2,2,1,1]

    The function will compute the optimal grouping into sets of distinct books
    to maximize the discount, and return the total price in cents (int).
    """
    if not isinstance(basket, list):
        raise TypeError("basket must be a list")

    # Determine whether basket is a list of ids or counts.
    counts = None
    if len(basket) == 5 and all(isinstance(x, int) for x in basket):
        # If all values fit into id ranges (0..4 or 1..5) treat as list of ids.
        if all(0 <= x <= 4 for x in basket) or all(1 <= x <= 5 for x in basket):
            # treat as ids
            counts = [0] * 5
            for b in basket:
                if 1 <= b <= 5:
                    counts[b - 1] += 1
                else:
                    counts[b] += 1
        else:
            # treat as counts-per-volume
            counts = list(basket)
            if any(x < 0 for x in counts):
                raise ValueError("counts must be non-negative")
            if len(counts) != 5:
                raise ValueError("counts list must have length 5")
    else:
        # treat as list of ids
        counts = [0] * 5
        for b in basket:
            if not isinstance(b, int):
                raise TypeError("book ids must be integers")
            if 1 <= b <= 5:
                counts[b - 1] += 1
            elif 0 <= b <= 4:
                counts[b] += 1
            else:
                raise ValueError("book ids must be in range 0..4 or 1..5")

    # Memoized recursion over states (tuple of counts)
    memo = {}

    def recurse(state):
        key = tuple(state)
        if key in memo:
            return memo[key]
        if all(c == 0 for c in state):
            memo[key] = 0
            return 0

        best = float('inf')
        positive_indices = [i for i, c in enumerate(state) if c > 0]
        max_group = len(positive_indices)
        # try all possible group sizes from 1..max_group
        for group_size in range(1, max_group + 1):
            # try every combination of distinct books of this size
            for combo in combinations(positive_indices, group_size):
                next_state = list(state)
                for idx in combo:
                    next_state[idx] -= 1
                cost = _group_price_cents(group_size) + recurse(next_state)
                if cost < best:
                    best = cost

        memo[key] = best
        return best

    return recurse(counts)
